INSERT INTO disciplinary_actions (ref, manager_name, manager_email, employee_name, employee_role, employee_branch, document_date, revaluation_date, warning_level, final_outcome, scenario, q_expected, q_happened, q_when, q_impact, evidence_types, evidence_description, prior_warnings, expectations, consequences, signature_drawn, submitted_at) VALUES
('GAF-DA-2026-6384','Arelis Acosta','Arelis.A@vitasyahc.com','Osvaldo Medina','EVV Specialist','PA','2026-06-24','2026-07-08','First Written Warning','','Attendance / Tardiness','Scheduled shift starts at 8am and it is expected that an attendance form be filled out prior to 8am in the event that the employee believes they will be late.','He arrived at 12:00 P.M. on 6/24/2026 and reported he would be late at 8:04 A.M. which is past his entry time.','6/24/2026','Arriving late affects the times you are available for meetings, questions, tasks and other workload assistance. Osvaldo is expected to arrive to his workstation at 9am EST and be available to complete any expected task.',ARRAY['Attendance Record']::text[],'','Verbal warning was issued 3/24/2026.','Osvaldo is expected to arrive to his workstation at 9am EST and be available to complete any expected task, as well as notify of any absence or tardiness before his entry time.','Further disciplinary action up to and including termination.',false,'2026-06-24'::timestamptz),
('GAF-DA-2026-7873','Arelis Acosta','Arelis.A@vitasyahc.com','Aleka Papatsoris','EVV Specialist','IN','2026-06-24','2026-07-08','Verbal Warning','','Inappropriate Conduct','Las faltas leves son aquellas acciones, omisiones, conductas o actitudes del trabajador que, aunque no constituyen una amenaza grave para el patrimonio, los valores, la reputacion o el correcto funcionamiento de la empresa, representan un incumplimiento de las normas internas, comprometiendo de manera menor la disciplina, la eficiencia o la armonia laboral que debe existir para mantener un buen clima laboral y cultura organizacional. Entre las faltas leves se incluyen, pero no se limitan a: 2. Incumplimiento de normas de menor impacto relacionadas con el orden y la disciplina que debe imperar en el ambiente de trabajo.','On 6/24/2026 Ally reached out her team lead stating that her coworkers were talking about a situation she was involved with. During the meeting, her coworkers explained that they were not talking about her or the situation after which Ally expressed, she felt a sarcastic tone from her team lead''s messages. Her team lead then asked her to show her which messages had a sarcastic tone to which Ally refused to identify the examples. Before the meeting had ended, Ally chose to stand up and leave without saying anything.','6/24/2026','Although the issue was addressed in an in-person meeting; Ally showed reluctance towards recognizing she could''ve been wrong and disregard for authority by walking out of a meeting prematurely. All of these things can affect her relationship with her peers and managers causing unnecessary tension.',ARRAY['Witnesses']::text[],'','None.','Ally is expected to take accountability and have humility when accepting a wrongdoing.','Further disciplinary action up to and including termination.',false,'2026-06-24'::timestamptz),
('GAF-DA-2026-9827','Marcela Gordon','marcela.g@vitasyahc.com','Juan Molina','Intake 1','Vitasya','2026-06-23','2026-07-07','First Written Warning','','Calls / Lead Follow-up','The employee received a verbal warning on 06/16/2026. His expectations were to improve calls and referral within the upcoming weeks.','Juan 79 3 Juan 95 2 Juan 90 2 Juan 89 4 Juan 89 5','Week of the 17th','Leads are behind and not being followed up on time due to lower call volume',ARRAY['Call Report']::text[],'Juan 79 3 Juan 95 2 Juan 90 2 Juan 89 4 Juan 89 5','Verbal warning provided on 6/16','Improvement needed by 7/7/26','Further disciplinary action up to and including termination.',false,'2026-06-23'::timestamptz),
('GAF-DA-2026-2645','Marcela Gordon','marcela.g@vitasyahc.com','Juan Molina','Intake 1','Vitasya','2026-06-16','2026-06-19','Verbal Warning','','Calls / Lead Follow-up','KPI metric for intake 1 states a minimum of 90 calls and 5 referrals completed per day, for at least 3 days out of the week.','6/8 - 56 calls, 0 referrals 6/9 - 56 calls, 4 referrals 6/10 - 71 calls, 4 referrals 6/11 - 97 calls, 3 referrals 6/12 - 100 calls, 2 referrals','Week of 6/8','Lower calls mean we are not meeting our speed to lead goals.',ARRAY['Call Report']::text[],'Intake 1 Daily calls stats','None','Improvements needed with calls and/or referrals per day.','Further disciplinary action up to and including termination.',false,'2026-06-16'::timestamptz),
('GAF-DA-2026-3947','Marcela Gordon','marcela.g@vitasyahc.com','Juan Molina','Intake 1','Vitasya','2026-06-16','2026-06-23','Verbal Warning','','Attendance / Tardiness','Scheduled shift starts at 8am and it is expected that an attendance form be filled out prior to 8am in the event that the employee believes they will be late.','Juan has consistently arrived past 8am.','June 9th arrival 8:35am, June 10th arrival 8:32am, June 11th arrival 8:25am, June 12th arrival 8:16am','Arriving late affects the times you are available for meetings, questions, tasks and after office hours workload assistance. If you are not available to make calls at 8am we can miss out on timely reach outs to valuable leads in your pipeline.',ARRAY['Attendance Record']::text[],'','','Juan is expected to arrive to his workstation at 9am EST and be available to complete any expected task.','Further disciplinary action up to and including termination.',false,'2026-06-16'::timestamptz),
('GAF-DA-2026-1674','Arelis Acosta','Arelis.A@vitasyahc.com','Navvad Owusu','EVV Specialist','GA West','2026-06-04','2026-07-10','Verbal Warning','','Operational Instructions','The employee has received multiple coaching conversations regarding proper EVV procedures; however, expectations continue to not be met. The employee is expected to make timely outreach calls, accurately document all interactions and contact attempts, approve eligible visits, and request timesheets, when necessary, escalate cases that need leadership guidance or resolution, employee was also expected to reduce phone usage during work hours. Improvement is required to ensure compliance with EVV processes and performance expectations.','On May 26, it was identified that the employee moved visits from May 23 and May 24 to the Unverified tab in an effort to improve productivity metrics. This expectation was addressed with the entire team during the EVV meeting on May 27 and also personally on her messages. On June 2, it was again observed that visits were being moved to Rejected status at the end of the day to improve productivity numbers. Further review showed that 22 of the 40 visits rejected that day were processed by the employee. Many of these visits only required timesheets, and several were rejected despite the visits being complete and eligible for approval. This action is not in accordance with EVV procedures and expectations.','May 26th, May 23rd, May 24th and May 27th.','Improperly moving visits to Unverified or Rejected status can delay caregiver payments, generate additional calls and complaints from caregivers and clients, increase operational workload, and create compliance and financial risks for the company.',ARRAY['Witnesses','Other']::text[],'Additional evidence reviewed on June 3 showed a visit that had been rejected without appropriate justification. Documentation on the visit indicated that the caregiver had left a note stating they were attending church with the client; however, the visit was still rejected by the employee. This demonstrates a failure to properly review visit documentation and follow established EVV approval procedures before taking action on a visit.','','Effective immediately, the employee is expected to follow all EVV procedures and guidelines when reviewing visits. Visits may only be moved to the Unverified or Rejected tabs when appropriate and in accordance with the following established processes; awaiting travel request approvals, no travel request after confirmation from program manager, no service provided confirmed by client, PA expired, no location for PSS, unable to contact either caregiver or client after more than three days and with approval from manager and hospitalization. The employee must thoroughly review all visit documentation, make required outreach attempts, accurately document all actions taken, request timesheets when necessary, and approve eligible visits whenever possible. Productivity metrics must never influence the status assigned to a visit. The employee is expected to demonstrate immediate and sustained improvement in accuracy, compliance, and adherence to EVV expectations.','Further disciplinary action up to and including termination.',false,'2026-06-04'::timestamptz);
